  selector:
    matchLabels:
      app.kubernetes.io/name: backup-restic
  template:
    metadata:
      labels:
        app.kubernetes.io/name: backup-restic
      annotations:
        checksum/config: f93590481ab4f887d6890b521b10691d7b194d4edfe70963ae3ae71a8a21921e
    spec:
      automountServiceAccountToken: false
      initContainers:
        - name: require-initialized-repositories
          image: docker.io/library/nginx:1.28.0
          command: [/bin/sh, -ec]
          args:
            - |
              test -s /data/keycloak/config || { echo 'Repository keycloak is missing its config; initialize it explicitly before deployment' >&2; exit 1; }
              for directory in data index keys locks snapshots; do
                test -d /data/keycloak/"$directory" || { echo "Repository keycloak is missing $directory" >&2; exit 1; }
              done
              test -s /data/other/config || { echo 'Repository other is missing its config; initialize it explicitly before deployment' >&2; exit 1; }
              for directory in data index keys locks snapshots; do
                test -d /data/other/"$directory" || { echo "Repository other is missing $directory" >&2; exit 1; }
              done
          volumeMounts:
            - name: data
              mountPath: /data
              readOnly: true
      containers:
        - name: writer
          image: docker.io/restic/rest-server@sha256:d2aff06f47eb38637dff580c3e6bce4af98f386c396a25d32eb6727ec96214a5
          command: [rest-server]
          args: [--path, /data, --listen, '127.0.0.1:8000', --no-auth, --append-only]
          volumeMounts:
            - name: data
              mountPath: /data
        - name: repository
          image: docker.io/restic/rest-server@sha256:d2aff06f47eb38637dff580c3e6bce4af98f386c396a25d32eb6727ec96214a5
          command: [rest-server]
          args: [--path, /data, --listen, '127.0.0.1:8001', --no-auth]
          volumeMounts:
            - name: data
              mountPath: /data
        - name: https
          image: docker.io/library/nginx:1.28.0
          ports:
            - name: https
              containerPort: 8443
          readinessProbe:
            tcpSocket:
              port: https
          volumeMounts:
            - name: nginx
              mountPath: /etc/nginx/nginx.conf
              subPath: nginx.conf
              readOnly: true
            - name: tls
              mountPath: /tls
              readOnly: true
            - name: auth-keycloak
              mountPath: /auth/keycloak
              readOnly: true
            - name: auth-other
              mountPath: /auth/other
              readOnly: true
      volumes:
        - name: data
          persistentVolumeClaim:
            claimName: "repository"
        - name: nginx
          configMap:
            name: backup-restic
        - name: tls
          secret:
            secretName: "repository-tls"
        - name: auth-keycloak
          secret:
            secretName: "keycloak-auth"
            items:
              - key: htpasswd
                path: htpasswd
        - name: auth-other
          secret:
            secretName: "other-auth"
            items:
              - key: htpasswd
                path: htpasswd

